    if month >= 10:
        start_year = enrollment_date.year
        semester = 'S1'
    elif month == 1:
        start_year = enrollment_date.year - 1
        semester = 'S1'
    elif month <= 7:
        start_year = enrollment_date.year - 1
        semester = 'S2'
    else:  # August / September
        start_year = enrollment_date.year - 1
        semester = 'SUM'

    return f"{start_year}-{start_year + 1}", semester


